using System.Text.Json;
using Biblia.Application.Interfaces;
using Biblia.Domain.Entities;
using Biblia.Domain.Rules;
using Biblia.Infrastructure.AppDatabase;
using Microsoft.Data.Sqlite;

namespace Biblia.Infrastructure.Repositories;

public sealed class PublicationService(Biblia.Infrastructure.AppDatabase.AppDatabase database,IClock clock) : IPublicationService
{
 private const string SelectPublication="SELECT Id,Name,Title,Subtitle,HeaderText,HeaderBackgroundColorHex,HeaderTextColorHex,TitleFontSize,TitleBold,TitleItalic,BrandingId,CreatedAt,UpdatedAt,TitleTextColorHex,OrganizationFontSize,OrganizationTextColorHex,SubtitleFontSize,SubtitleTextColorHex,HeaderDetailFontSize,HeaderDetailTextColorHex,LogoWidth,LogoHeight FROM Publication";
 public async Task<IReadOnlyList<Publication>> GetAllAsync(CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText=SelectPublication+" ORDER BY Name COLLATE NOCASE";await using var r=await q.ExecuteReaderAsync(ct);var a=new List<Publication>();while(await r.ReadAsync(ct))a.Add(Read(r));return a;}
 public async Task<Publication?> GetAsync(long id,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText=SelectPublication+" WHERE Id=$id";q.Parameters.AddWithValue("$id",id);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?Read(r):null;}
 public async Task<Publication> SaveAsync(Publication p,CancellationToken ct=default){var name=Publication.NormalizeName(p.Name);var bg=Publication.NormalizeHex(p.HeaderBackgroundColorHex);var legacy=Publication.NormalizeHex(p.HeaderTextColorHex);var title=Publication.NormalizeHex(p.TitleTextColorHex)??legacy;var organization=Publication.NormalizeHex(p.OrganizationTextColorHex)??legacy;var subtitle=Publication.NormalizeHex(p.SubtitleTextColorHex)??legacy;var detail=Publication.NormalizeHex(p.HeaderDetailTextColorHex)??legacy;if(p.TitleFontSize is <8 or >72||p.OrganizationFontSize is <8 or >72||p.SubtitleFontSize is <8 or >72||p.HeaderDetailFontSize is <8 or >72)throw new ArgumentException("Os tamanhos de fonte devem estar entre 8 e 72.");var now=clock.UtcNow;await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText=p.Id==0?"INSERT INTO Publication(Name,Title,Subtitle,HeaderText,HeaderBackgroundColorHex,HeaderTextColorHex,TitleTextColorHex,TitleFontSize,TitleBold,TitleItalic,BrandingId,OrganizationFontSize,OrganizationTextColorHex,SubtitleFontSize,SubtitleTextColorHex,HeaderDetailFontSize,HeaderDetailTextColorHex,LogoWidth,LogoHeight,CreatedAt,UpdatedAt) VALUES($n,$t,$s,$h,$bg,$legacy,$title,$titleSize,$b,$i,$brand,$orgSize,$org,$subSize,$sub,$detailSize,$detail,$logoW,$logoH,$now,$now);SELECT last_insert_rowid();":"UPDATE Publication SET Name=$n,Title=$t,Subtitle=$s,HeaderText=$h,HeaderBackgroundColorHex=$bg,HeaderTextColorHex=$legacy,TitleTextColorHex=$title,TitleFontSize=$titleSize,TitleBold=$b,TitleItalic=$i,BrandingId=$brand,OrganizationFontSize=$orgSize,OrganizationTextColorHex=$org,SubtitleFontSize=$subSize,SubtitleTextColorHex=$sub,HeaderDetailFontSize=$detailSize,HeaderDetailTextColorHex=$detail,LogoWidth=$logoW,LogoHeight=$logoH,UpdatedAt=$now WHERE Id=$id;SELECT $id;";if(p.Id!=0)q.Parameters.AddWithValue("$id",p.Id);q.Parameters.AddWithValue("$n",name);q.Parameters.AddWithValue("$t",(object?)p.Title?.Trim()??DBNull.Value);q.Parameters.AddWithValue("$s",(object?)p.Subtitle?.Trim()??DBNull.Value);q.Parameters.AddWithValue("$h",(object?)p.HeaderText?.Trim()??DBNull.Value);q.Parameters.AddWithValue("$bg",(object?)bg??DBNull.Value);q.Parameters.AddWithValue("$legacy",(object?)legacy??DBNull.Value);q.Parameters.AddWithValue("$title",(object?)title??DBNull.Value);q.Parameters.AddWithValue("$titleSize",(object?)p.TitleFontSize??DBNull.Value);q.Parameters.AddWithValue("$b",p.TitleBold);q.Parameters.AddWithValue("$i",p.TitleItalic);q.Parameters.AddWithValue("$brand",(object?)p.BrandingId??DBNull.Value);q.Parameters.AddWithValue("$orgSize",(object?)p.OrganizationFontSize??DBNull.Value);q.Parameters.AddWithValue("$org",(object?)organization??DBNull.Value);q.Parameters.AddWithValue("$subSize",(object?)p.SubtitleFontSize??DBNull.Value);q.Parameters.AddWithValue("$sub",(object?)subtitle??DBNull.Value);q.Parameters.AddWithValue("$detailSize",(object?)p.HeaderDetailFontSize??DBNull.Value);q.Parameters.AddWithValue("$detail",(object?)detail??DBNull.Value);q.Parameters.AddWithValue("$logoW",(object?)p.LogoWidth??DBNull.Value);q.Parameters.AddWithValue("$logoH",(object?)p.LogoHeight??DBNull.Value);q.Parameters.AddWithValue("$now",now.ToString("O"));try{var id=Convert.ToInt64(await q.ExecuteScalarAsync(ct));return (await GetAsync(id,ct))!;}catch(SqliteException ex)when(ex.SqliteErrorCode==19){throw new InvalidOperationException("Já existe uma publicação com este nome.",ex);}}
 public async Task DeleteAsync(long id,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="DELETE FROM Publication WHERE Id=$id";q.Parameters.AddWithValue("$id",id);await q.ExecuteNonQueryAsync(ct);}
 public async Task<OrganizationBranding?> GetBrandingAsync(CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT Id,Name,Logo,LogoContentType,CreatedAt,UpdatedAt FROM OrganizationBranding ORDER BY Id LIMIT 1";await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?new(r.GetInt64(0),r.GetString(1),r.IsDBNull(2)?null:(byte[])r[2],r.IsDBNull(3)?null:r.GetString(3),DateTimeOffset.Parse(r.GetString(4)),DateTimeOffset.Parse(r.GetString(5))):null;}
 public async Task SaveBrandingAsync(string name,byte[]? logo,string? type,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Informe o nome da igreja/ministério.");if(logo?.Length>5*1024*1024)throw new ArgumentException("A logomarca deve ter no máximo 5 MB.");if(logo is not null&&type is not ("image/png" or "image/jpeg"))throw new ArgumentException("Selecione uma imagem PNG ou JPG válida.");var old=await GetBrandingAsync(ct);await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText=old is null?"INSERT INTO OrganizationBranding(Name,Logo,LogoContentType,CreatedAt,UpdatedAt) VALUES($n,$l,$t,$now,$now)":"UPDATE OrganizationBranding SET Name=$n,Logo=$l,LogoContentType=$t,UpdatedAt=$now WHERE Id=$id";q.Parameters.AddWithValue("$n",name.Trim());q.Parameters.AddWithValue("$l",(object?)logo??DBNull.Value);q.Parameters.AddWithValue("$t",(object?)type??DBNull.Value);q.Parameters.AddWithValue("$now",clock.UtcNow.ToString("O"));if(old is not null)q.Parameters.AddWithValue("$id",old.Id);await q.ExecuteNonQueryAsync(ct);}
 public async Task AddReferenceAsync(long p,long t,long r,CancellationToken ct=default){if(p<=0||t<=0||r<=0)throw new ArgumentException("Publicação, tema e referência são obrigatórios.");await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText="INSERT OR IGNORE INTO PublicationThemeReference(PublicationId,ThemeId,ReferenceId,CreatedAt,UpdatedAt) VALUES($p,$t,$r,$now,$now); INSERT OR IGNORE INTO PublicationContent(PublicationId,ThemeId,ReferenceId,SortOrder,CreatedAt,UpdatedAt) SELECT $p,$t,$r,COALESCE((SELECT MAX(SortOrder)+1 FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t),0),$now,$now WHERE EXISTS(SELECT 1 FROM ReferenceTheme WHERE ThemeId=$t AND ReferenceId=$r);";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);q.Parameters.AddWithValue("$r",r);q.Parameters.AddWithValue("$now",clock.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}
 public async Task RemoveReferenceAsync(long p,long t,long r,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText="DELETE FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t AND ReferenceId=$r;DELETE FROM PublicationThemeReference WHERE PublicationId=$p AND ThemeId=$t AND ReferenceId=$r;";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);q.Parameters.AddWithValue("$r",r);await q.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}
 public async Task<IReadOnlyList<PublicationContentItem>> GetContentAsync(long p,long t,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT Id,PublicationId,ThemeId,SortOrder,ReferenceId,BlockJson FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t ORDER BY SortOrder,Id";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);await using var r=await q.ExecuteReaderAsync(ct);var a=new List<PublicationContentItem>();while(await r.ReadAsync(ct))a.Add(new(r.GetInt64(0),r.GetInt64(1),r.GetInt64(2),r.GetInt32(3),r.IsDBNull(4)?null:r.GetInt64(4),r.IsDBNull(5)?null:JsonSerializer.Deserialize<ThemeTextBlock>(r.GetString(5))));return a;}
 public async Task ApplyAutomaticOrderingAsync(long p,long t,CancellationToken ct=default)
 {
     var items=(await GetContentAsync(p,t,ct)).ToList();
     if(items.Count<2)return;
     await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();
     q.CommandText="SELECT OrderingMode FROM Theme WHERE Id=$t;";q.Parameters.AddWithValue("$t",t);
     if((ThemeOrderingMode)Convert.ToInt32(await q.ExecuteScalarAsync(ct)??throw new KeyNotFoundException("Tema não encontrado."))!=ThemeOrderingMode.Canonical)return;
     q.Parameters.Clear();q.CommandText="SELECT pc.Id,r.BookReferenceId,r.Chapter,r.VerseStart,r.VerseEnd,pc.ReferenceId FROM PublicationContent pc JOIN SavedReference r ON r.Id=pc.ReferenceId WHERE pc.PublicationId=$p AND pc.ThemeId=$t;";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);
     var keys=new Dictionary<long,(int,int,int,int,long)>();await using(var r=await q.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))keys[r.GetInt64(0)]=BibleCanonicalOrder.Key(r.GetInt32(1),r.GetInt32(2),r.GetInt32(3),r.GetInt32(4),r.GetInt64(5));
     var original=items.Select(x=>x.Id).ToArray();
     var verses=items.Where(x=>x.ReferenceId is not null).OrderBy(x=>keys.GetValueOrDefault(x.Id,(int.MaxValue,int.MaxValue,int.MaxValue,int.MaxValue,long.MaxValue))).ToArray();
     var next=0;for(var i=0;i<items.Count;i++)if(items[i].ReferenceId is not null)items[i]=verses[next++];
     if(!items.Select(x=>x.Id).SequenceEqual(original))await Persist(p,t,items,ct);
 }
 public async Task SynchronizeLegacyThemeContentAsync(long p,long t,CancellationToken ct=default)
 {
     var target=(await GetContentAsync(p,t,ct)).ToList();
     await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT Id,SortOrder,ReferenceId,BlockJson FROM ThemeContent WHERE ThemeId=$t ORDER BY SortOrder,Id";q.Parameters.AddWithValue("$t",t);await using var r=await q.ExecuteReaderAsync(ct);var source=new List<PublicationContentItem>();while(await r.ReadAsync(ct))source.Add(new(r.GetInt64(0),p,t,r.GetInt32(1),r.IsDBNull(2)?null:r.GetInt64(2),r.IsDBNull(3)?null:JsonSerializer.Deserialize<ThemeTextBlock>(r.GetString(3))));
     var missing=source.Where(x=>x.TextBlock is not null&&!target.Any(y=>y.TextBlock==x.TextBlock)).ToArray();if(missing.Length==0)return;
     foreach(var block in missing)await SaveTextBlockAsync(p,t,null,block.TextBlock!,ct);
     target=(await GetContentAsync(p,t,ct)).ToList();var used=new HashSet<long>();var ordered=new List<PublicationContentItem>();
     foreach(var item in source){var match=item.ReferenceId is long reference?target.FirstOrDefault(x=>x.ReferenceId==reference&&!used.Contains(x.Id)):target.FirstOrDefault(x=>x.TextBlock==item.TextBlock&&!used.Contains(x.Id));if(match is not null){ordered.Add(match);used.Add(match.Id);}}
     ordered.AddRange(target.Where(x=>!used.Contains(x.Id)));await Persist(p,t,ordered,ct);
 }
 public async Task MoveContentAsync(long p,long t,long id,int delta,CancellationToken ct=default){var a=(await GetContentAsync(p,t,ct)).ToList();var i=a.FindIndex(x=>x.Id==id);var to=i+Math.Sign(delta);if(i<0||to<0||to>=a.Count)return;(a[i],a[to])=(a[to],a[i]);await Persist(p,t,a,ct);}
 public async Task<long> SaveTextBlockAsync(long p,long t,long? id,ThemeTextBlock b,CancellationToken ct=default){var json=JsonSerializer.Serialize(b);await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText=id is null?"INSERT INTO PublicationContent(PublicationId,ThemeId,BlockJson,SortOrder,CreatedAt,UpdatedAt) VALUES($p,$t,$j,COALESCE((SELECT MAX(SortOrder)+1 FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t),0),$n,$n);SELECT last_insert_rowid();":"UPDATE PublicationContent SET BlockJson=$j,UpdatedAt=$n WHERE Id=$id AND PublicationId=$p AND ThemeId=$t;SELECT $id;";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);q.Parameters.AddWithValue("$j",json);q.Parameters.AddWithValue("$n",clock.UtcNow.ToString("O"));if(id is not null)q.Parameters.AddWithValue("$id",id.Value);return Convert.ToInt64(await q.ExecuteScalarAsync(ct));}
 public async Task DeleteTextBlockAsync(long p,long t,long id,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="DELETE FROM PublicationContent WHERE Id=$id AND PublicationId=$p AND ThemeId=$t AND ReferenceId IS NULL;";q.Parameters.AddWithValue("$id",id);q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);if(await q.ExecuteNonQueryAsync(ct)==0)throw new KeyNotFoundException("Bloco não encontrado nesta publicação.");}
 public async Task<PublicationThemeStatus> GetThemeStatusAsync(long p,long t,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT (SELECT COUNT(*) FROM ThemeContent WHERE ThemeId=$t),(SELECT COUNT(*) FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t),(SELECT COUNT(*) FROM ThemeContent x WHERE x.ThemeId=$t AND ((x.ReferenceId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM PublicationContent y WHERE y.PublicationId=$p AND y.ThemeId=$t AND y.ReferenceId=x.ReferenceId)) OR (x.BlockJson IS NOT NULL AND NOT EXISTS(SELECT 1 FROM PublicationContent y WHERE y.PublicationId=$p AND y.ThemeId=$t AND y.BlockJson=x.BlockJson))))";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var source=r.GetInt32(0);var target=r.GetInt32(1);var missing=r.GetInt32(2);return target==0?PublicationThemeStatus.None:source>0&&missing==0?PublicationThemeStatus.Complete:PublicationThemeStatus.Partial;}
 public async Task LinkCompleteThemeAsync(long p,long t,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText="INSERT OR IGNORE INTO PublicationThemeReference(PublicationId,ThemeId,ReferenceId,CreatedAt,UpdatedAt) SELECT $p,$t,ReferenceId,$n,$n FROM ThemeContent WHERE ThemeId=$t AND ReferenceId IS NOT NULL; INSERT INTO PublicationContent(PublicationId,ThemeId,ReferenceId,SortOrder,CreatedAt,UpdatedAt) SELECT $p,$t,x.ReferenceId,COALESCE((SELECT MAX(SortOrder)+1 FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t),0)+x.SortOrder,$n,$n FROM ThemeContent x WHERE x.ThemeId=$t AND x.ReferenceId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM PublicationContent y WHERE y.PublicationId=$p AND y.ThemeId=$t AND y.ReferenceId=x.ReferenceId); INSERT INTO PublicationContent(PublicationId,ThemeId,BlockJson,SortOrder,CreatedAt,UpdatedAt) SELECT $p,$t,x.BlockJson,COALESCE((SELECT MAX(SortOrder)+1 FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t),0)+x.SortOrder,$n,$n FROM ThemeContent x WHERE x.ThemeId=$t AND x.BlockJson IS NOT NULL AND NOT EXISTS(SELECT 1 FROM PublicationContent y WHERE y.PublicationId=$p AND y.ThemeId=$t AND y.BlockJson=x.BlockJson);";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);q.Parameters.AddWithValue("$n",clock.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}
 public async Task UnlinkThemeAsync(long p,long t,CancellationToken ct=default){await using var c=await database.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="DELETE FROM PublicationContent WHERE PublicationId=$p AND ThemeId=$t;DELETE FROM PublicationThemeReference WHERE PublicationId=$p AND ThemeId=$t;";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$t",t);await q.ExecuteNonQueryAsync(ct);}
 async Task Persist(long p,long t,List<PublicationContentItem> a,CancellationToken ct){await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);foreach(var x in a.Select((v,i)=>(v,i))){await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText="UPDATE PublicationContent SET SortOrder=$o WHERE Id=$id";q.Parameters.AddWithValue("$o",x.i+100000);q.Parameters.AddWithValue("$id",x.v.Id);await q.ExecuteNonQueryAsync(ct);}foreach(var x in a.Select((v,i)=>(v,i))){await using var q=c.CreateCommand();q.Transaction=(SqliteTransaction)tx;q.CommandText="UPDATE PublicationContent SET SortOrder=$o WHERE Id=$id";q.Parameters.AddWithValue("$o",x.i);q.Parameters.AddWithValue("$id",x.v.Id);await q.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);}
 static Publication Read(SqliteDataReader r){var p=new Publication(r.GetInt64(0),r.GetString(1),r.IsDBNull(2)?null:r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.IsDBNull(7)?null:r.GetDouble(7),r.GetBoolean(8),r.GetBoolean(9),r.IsDBNull(10)?null:r.GetInt64(10),DateTimeOffset.Parse(r.GetString(11)),DateTimeOffset.Parse(r.GetString(12)));p.TitleTextColorHex=r.IsDBNull(13)?p.HeaderTextColorHex:r.GetString(13);p.OrganizationFontSize=r.IsDBNull(14)?null:r.GetDouble(14);p.OrganizationTextColorHex=r.IsDBNull(15)?p.HeaderTextColorHex:r.GetString(15);p.SubtitleFontSize=r.IsDBNull(16)?null:r.GetDouble(16);p.SubtitleTextColorHex=r.IsDBNull(17)?p.HeaderTextColorHex:r.GetString(17);p.HeaderDetailFontSize=r.IsDBNull(18)?null:r.GetDouble(18);p.HeaderDetailTextColorHex=r.IsDBNull(19)?p.HeaderTextColorHex:r.GetString(19);p.LogoWidth=r.IsDBNull(20)?null:r.GetDouble(20);p.LogoHeight=r.IsDBNull(21)?null:r.GetDouble(21);return p;}
}
